"""Register only actually inspected primary passages and explicit access gaps."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[4];HERE=pathlib.Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,d):(HERE/n).write_text(json.dumps(d,indent=2)+'\n',encoding='utf8')
def main():
 cache=ROOT/'build/ethernet-wire-sources';downloads={r['path'].split('/')[-1]:r for r in json.loads((cache/'downloads.json').read_text()) if 'path'in r};rows=[]
 specs=[('WORKSHOP','IEEE802.3 Ethernet workshop','David Law','Version1.1 March2011',2011,'workshop.pdf',['Slides5–7,9–10,14 textual frame/layer/media/size statements; no visual-diagram inspection']),('VTAG','Provider Bridges','IEEE802.1','P802.1ad/D2.4 unapproved draft September27 2004',2004,'vlan-draft.pdf',['8.7 printed46–47 learning/capacity; 9.1–9.6 printed74–77 tag purpose/encoding/CFI/VID']),('IPETH','IP datagrams over Ethernet','Charles Hornig','RFC894 April1984',1984,'rfc894.txt',['Frame Format and Address Mappings printed1–2']),('HOST','Internet communication layers','R. Braden editor','RFC1122 October1989',1989,'rfc1122.txt',['1.1.3 printed8–10 application/transport/internet/link architecture']),('TCP','Transmission Control Protocol','W. Eddy editor','RFC9293 August2022',2022,'rfc9293.txt',['2.2 byte-stream service; 3.7 segmentation and absent message-boundary guarantee']),('HTTP','HTTP Semantics','R. Fielding; M. Nottingham; J. Reschke','RFC9110 June2022',2022,'rfc9110.txt',['3.3 connections, stateless semantics and connection/user identity'])]
 for key,title,author,edition,year,name,loc in specs:
  capture=downloads[name];assert sha(ROOT/capture['path'])==capture['sha256'];rows.append(dict(id='R-EW-'+key,title=title,authors=[author],edition=edition,year=year,kind='standard' if key!='WORKSHOP' else 'presentation',url=capture['url'],access='Named primary passages inspected',domains=['T39'],role='primary',reason='Distinguish wire/service/model/authority contracts and changed assumptions',prerequisites=['C17 array bounds and retained Ethernet core'],locators=loc,assignable=True,inspection=dict(date='2026-10-18',method='Actual selected primary text passages read from captured PDF extraction or original RFC text',scope=loc,limits='Selected passages only; historical/draft identity preserved; no full conformance, visual or independent-review claim',capture={k:capture[k] for k in ['path','sha256']})))
 old=json.loads((ROOT/'research/v5/expansion/legacy_ethernet_phy/resources.json').read_text(encoding='utf8'))['resources']
 for source,loc in [('R-EP-LAN',['3.2–3.2.4 printed27–29 negotiation, parallel detection and half/full duplex']),('R-EP-BOARD8',['6.11/Table11 printed28–29 RMII route and bridge/jumper assignments']),('R-EP-BOARD11',['7.11/Table11 printed29–30 RMII route and bridge/jumper assignments'])]:
  original=next((x for x in old if x['id']==source),None)
  if original is None:
   if source=='R-EP-LAN':original=next(x for x in old if 'LAN8742' in x['title'])
   else:raise ValueError(source)
  r=dict(original);r['id']=source.replace('R-EP-','R-EW-');r['locators']=loc;r['inspection']=dict(original['inspection']);r['inspection'].update(date='2026-10-18',scope=loc,method='Actual selected local primary PDF extraction read' if source!='R-EP-BOARD11' else 'Actual primary web PDF extracted selected text read; no local capture digest');rows.append(r)
 write('resources.json',dict(resources=rows))
 write('source_access.json',dict(date='2026-10-18',actor='/root/author_batch',scope='Bounded actual primary passages for twelve original objective/variant pairs',resources=[dict(id=r['id'],locators=r['locators'],capture=r['inspection'].get('capture')) for r in rows],gaps=['Exact current normative IEEE802.3/802.1Q bodies not inspected; workshop and unapproved2004 draft do not substitute for them.','Manual revision is not observed board/PHY identity.','No independent review, learner or physical observation.'],library_lookup=dict(scope='Read-only schema4 exact standard queries; no old/opaque traversal',result='802.1Q none;802.3 two secondary publications, no exact standard found',capture='build/ethernet-wire-sources/lookup.json',sha256=sha(cache/'lookup.json'))))
 names=['resources.json','source_access.json','audit.md','register_sources.py'];write('research_gate.json',dict(status='passage-inspected',scope='Selected T39 authoring sources, not independent acceptance',resource_ids=[r['id'] for r in rows],research_input_sha256={'research/v5/expansion/legacy_ethernet_wire/'+n:sha(HERE/n) for n in names},limitations=['Exact final standards source gap and actual physical/independent obligations remain explicit.']))
 print('PASS selected Ethernet sources',len(rows))
if __name__=='__main__':main()
